import os
from github import Github
_client = Github(os.environ['GITHUB_TOKEN'])

def _get_repo(repo_name):
    return _client.get_repo(repo_name)

def grant_repo_collaborator_access(repo_name: str, username: str, permission: str='push') -> dict:
    if permission not in ('pull', 'triage', 'push', 'maintain', 'admin'):
        return {'ok': False, 'error': f'invalid permission: {permission}'}
    repo = _get_repo(repo_name)
    invitation = repo.add_to_collaborators(username, permission=permission)
    # Cancel older pending invitations for the same user so only the newest remains
    new_id = getattr(invitation, 'id', None)
    cancelled = []
    for pending in repo.get_pending_invitations():
        invitee = getattr(pending, 'invitee', None)
        if invitee is not None and invitee.login == username and pending.id != new_id:
            repo.remove_invitation(pending.id)
            cancelled.append(pending.id)
    return {'ok': True, 'repo': repo_name, 'user': username, 'permission': permission, 'invitation_id': getattr(invitation, 'id', None), 'cancelled_invitations': cancelled}
